const path = require('path');
const { greet } = require('./utils');
const { loadConfig } = require('./config');

// Resolved against the module, not the process cwd, so the app runs from
// anywhere and still finds the config that ships beside it.
const CONFIG_PATH = path.join(__dirname, '..', 'app.conf');

function main() {
  let config;
  try {
    config = loadConfig(CONFIG_PATH);
    if (config.name === undefined) {
      throw new Error(`Missing required key 'name' in ${CONFIG_PATH}`);
    }
  } catch (err) {
    console.error(`Configuration error: ${err.message}`);
    process.exit(1);
  }
  console.log(greet(config.name));
}

main();

const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const path = require('path');

const { parseConfig, loadConfig } = require('../src/config');

test('parses a key=value line', () => {
  assert.strictEqual(parseConfig('name=world').name, 'world');
});

test('trims whitespace around keys and values', () => {
  assert.strictEqual(parseConfig('  name  =  world  ').name, 'world');
});

test('skips blank lines and whole-line comments', () => {
  const config = parseConfig('# a comment\n\nname=world\n');
  assert.deepStrictEqual(Object.keys(config), ['name']);
});

test('keeps a "#" that appears inside a value', () => {
  assert.strictEqual(parseConfig('color=#ff0000').color, '#ff0000');
});

test('keeps "=" that appears inside a value', () => {
  assert.strictEqual(parseConfig('token=a=b=c').token, 'a=b=c');
});

test('accepts an empty value', () => {
  assert.strictEqual(parseConfig('name=').name, '');
});

test('rejects a line with no "="', () => {
  assert.throws(() => parseConfig('DEBUG'), /expected key=value: DEBUG/);
});

test('rejects a line with an empty key', () => {
  assert.throws(() => parseConfig('=value'), /empty key/);
});

test('resolves duplicate keys last-wins', () => {
  assert.strictEqual(parseConfig('name=first\nname=second').name, 'second');
});

test('handles CRLF line endings', () => {
  const config = parseConfig('name=world\r\nport=8080\r\n');
  assert.strictEqual(config.name, 'world');
  assert.strictEqual(config.port, '8080');
});

test('a "__proto__" key cannot reach Object.prototype', () => {
  const config = parseConfig('__proto__=polluted');
  assert.strictEqual(config.__proto__, 'polluted');
  assert.strictEqual({}.__proto__, Object.prototype);
});

test('loadConfig reports the path when the file is missing', () => {
  const missing = path.join(__dirname, 'does-not-exist.conf');
  assert.throws(() => loadConfig(missing), {
    message: `Cannot read config file at ${missing}`,
  });
});

test('loadConfig reads the shipped app.conf', () => {
  const shipped = path.join(__dirname, '..', 'app.conf');
  assert.strictEqual(loadConfig(shipped).name, 'world');
});

test('every line of the shipped app.conf parses', () => {
  const text = fs.readFileSync(path.join(__dirname, '..', 'app.conf'), 'utf8');
  assert.doesNotThrow(() => parseConfig(text));
});

