const path = require('path');
const { greet } = require('./utils');
const { ConfigError, loadConfig } = require('./config');

// Resolved against the module, not the process cwd, so the app runs from
// anywhere and still finds the config that ships beside it.
const CONFIG_PATH = path.join(__dirname, '..', 'app.conf');

function main() {
  let config;
  try {
    config = loadConfig(CONFIG_PATH);
    if (!config.name) {
      throw new ConfigError(
        `Missing or empty required key 'name' in ${CONFIG_PATH}`
      );
    }
  } catch (err) {
    // Only an operator-correctable problem becomes a friendly message; a
    // genuine bug keeps its stack instead of posing as bad configuration.
    if (!(err instanceof ConfigError)) throw err;
    console.error(`Configuration error: ${err.message}`);
    // Setting the code rather than calling process.exit lets stderr flush.
    process.exitCode = 1;
    return;
  }
  console.log(greet(config.name));
}

if (require.main === module) {
  main();
}

module.exports = { main, CONFIG_PATH };

const test = require('node:test');
const assert = require('node:assert');
const { spawnSync } = require('node:child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');

const SRC = path.join(__dirname, '..', 'src');
const ENTRY = path.join(SRC, 'index.js');

function run(entry, cwd) {
  return spawnSync(process.execPath, [entry], { cwd, encoding: 'utf8' });
}

// Copies the app into a scratch dir so a test can vary app.conf without
// touching the checkout's own config.
function stageApp(confText) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'config-app-'));
  fs.mkdirSync(path.join(dir, 'src'));
  for (const file of ['index.js', 'config.js', 'utils.js']) {
    fs.copyFileSync(path.join(SRC, file), path.join(dir, 'src', file));
  }
  fs.writeFileSync(path.join(dir, 'app.conf'), confText);
  return path.join(dir, 'src', 'index.js');
}

test('runs from a directory other than the repo root', () => {
  const result = run(ENTRY, os.tmpdir());
  assert.strictEqual(result.status, 0, result.stderr);
  assert.strictEqual(result.stdout.trim(), 'Hello, world!');
});

test('greets the name configured in app.conf', () => {
  const result = run(stageApp('name=Ada\n'));
  assert.strictEqual(result.status, 0, result.stderr);
  assert.strictEqual(result.stdout.trim(), 'Hello, Ada!');
});

test('exits 1 when app.conf has no name key', () => {
  const result = run(stageApp('# no name here\n'));
  assert.strictEqual(result.status, 1);
  assert.match(result.stderr, /Missing or empty required key 'name'/);
});

test('exits 1 when name is present but empty', () => {
  const result = run(stageApp('name=\n'));
  assert.strictEqual(result.status, 1);
  assert.match(result.stderr, /Missing or empty required key 'name'/);
});

test('exits 1 on a malformed config line', () => {
  const result = run(stageApp('name=world\nDEBUG\n'));
  assert.strictEqual(result.status, 1);
  assert.match(result.stderr, /Invalid config line \(expected key=value\): DEBUG/);
});

test('exits 1 when app.conf is missing entirely', () => {
  const entry = stageApp('name=world\n');
  fs.rmSync(path.join(path.dirname(entry), '..', 'app.conf'));
  const result = run(entry);
  assert.strictEqual(result.status, 1);
  assert.match(result.stderr, /Cannot read config file at /);
});

test('a non-config failure is not reported as a configuration error', () => {
  const entry = stageApp('name=world\n');
  // greet() is the one dependency outside the config path; breaking it must
  // surface as a real crash, not a friendly "Configuration error" line.
  fs.writeFileSync(
    path.join(path.dirname(entry), 'utils.js'),
    'function greet() { throw new TypeError("boom"); }\nmodule.exports = { greet };\n'
  );
  const result = run(entry);
  assert.notStrictEqual(result.status, 0);
  assert.doesNotMatch(result.stderr, /Configuration error/);
  assert.match(result.stderr, /TypeError: boom/);
});

